package com.skyrpg.pets.client.model;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeDeformation;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * The Jack o'Lantern pet's cubes and their UVs, and which parts each rarity shows. GENERATED by tools/art/generate_pets.py from the
 * same cube table the textures are painted from: edit the table there, never this file.
 */
final class JackPetLayout {
    /** Textures: textures/entity/pet/jack_&lt;rarity&gt;.png, and _glow.png for the rarities in {@link #GLOW_RARITIES}. */
    static final String NAME = "jack";
    /** Model pixels to player model pixels: how big the pet floats at the shoulder. */
    static final float SCALE = 0.72f;
    /** Whether some texels are see-through (drawn with the translucent entity render type). */
    static final boolean TRANSLUCENT = false;
    /** Bit r (0 = Common) set: that rarity has a glow layer, drawn fullbright. */
    static final int GLOW_RARITIES = 0b11111;
    /** Parts only some rarities show: RARITY_PARTS[i] is shown for rarity r when bit r of RARITY_MASKS[i] is set. */
    static final String[] RARITY_PARTS = {"arm_r", "arm_l", "wisp", "halo"};
    static final int[] RARITY_MASKS = {0b11110, 0b11110, 0b11100, 0b10000};

    private JackPetLayout() {
    }

    static LayerDefinition create() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        PartDefinition p_pet = root.addOrReplaceChild("pet",
        CubeListBuilder.create()
                , PartPose.offset(0f, 0f, 0f));
        PartDefinition p_head = p_pet.addOrReplaceChild("head",
        CubeListBuilder.create()
                .texOffs(0, 0).addBox(-4f, -4f, -4f, 8f, 8f, 8f)
                .texOffs(32, 0).addBox(-6f, -3f, -3f, 2f, 6f, 6f, new CubeDeformation(0f, 0f, 0.25f))
                .mirror(true)
                .texOffs(32, 0).addBox(4f, -3f, -3f, 2f, 6f, 6f, new CubeDeformation(0f, 0f, 0.25f))
                , PartPose.offset(0f, 0f, 0f));
        PartDefinition p_stem = p_head.addOrReplaceChild("stem",
        CubeListBuilder.create()
                .texOffs(12, 16).addBox(-1f, -2.25f, -1f, 2f, 2f, 2f, new CubeDeformation(0f, 0.25f, 0f))
                .texOffs(0, 16).addBox(-1.5f, -3.5f, -1.5f, 3f, 1f, 3f)
                , PartPose.offsetAndRotation(0f, -4f, 0f, 0f, 0f, 0.18f));
        p_stem.addOrReplaceChild("curl",
        CubeListBuilder.create()
                .texOffs(0, 20).addBox(-0.25f, -0.25f, -0.5f, 2f, 1f, 1f, new CubeDeformation(-0.25f, 0f, 0f))
                .texOffs(6, 20).addBox(1f, 0.75f, -0.5f, 1f, 1f, 1f)
                , PartPose.offset(1f, -2f, 0f));
        p_stem.addOrReplaceChild("leaf",
        CubeListBuilder.create()
                .texOffs(28, 16).addBox(-3.25f, -3f, 0f, 3f, 3f, 0f)
                , PartPose.offsetAndRotation(-1f, -1f, 0f, 0f, 0f, 0.35f));
        p_head.addOrReplaceChild("arm_r",
        CubeListBuilder.create()
                .texOffs(56, 16).addBox(-3f, -0.5f, -0.5f, 3f, 1f, 1f)
                , PartPose.offsetAndRotation(-6f, 0f, 0f, 0f, 0f, 0.5f));
        p_head.addOrReplaceChild("arm_l",
        CubeListBuilder.create()
                .mirror(true)
                .texOffs(56, 16).addBox(0f, -0.5f, -0.5f, 3f, 1f, 1f)
                , PartPose.offsetAndRotation(6f, 0f, 0f, 0f, 0f, -0.5f));
        p_head.addOrReplaceChild("halo",
        CubeListBuilder.create()
                .texOffs(38, 16).addBox(-4f, -0.5f, -4.125f, 8f, 1f, 1f, new CubeDeformation(0f, -0.25f, -0.125f))
                .texOffs(38, 16).addBox(-4f, -0.5f, 3.125f, 8f, 1f, 1f, new CubeDeformation(0f, -0.25f, -0.125f))
                .texOffs(48, 0).addBox(-4.125f, -0.5f, -3f, 1f, 1f, 6f, new CubeDeformation(-0.125f, -0.25f, 0.25f))
                .texOffs(48, 0).addBox(3.125f, -0.5f, -3f, 1f, 1f, 6f, new CubeDeformation(-0.125f, -0.25f, 0.25f))
                , PartPose.offsetAndRotation(0f, -10f, 0f, -0.1f, 0f, 0f));
        p_pet.addOrReplaceChild("wisp",
        CubeListBuilder.create()
                .texOffs(20, 16).addBox(-1f, -1f, -1f, 2f, 2f, 2f)
                .texOffs(34, 16).addBox(-0.5f, -3f, -0.5f, 1f, 2f, 1f)
                , PartPose.offset(7.5f, -6.5f, 0f));
        return LayerDefinition.create(mesh, 64, 64);
    }
}
